-- PT120-S4-Q18. Batch 03.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch03$PT120-S4-Q18$batch03$ AND q.stimulus=$batch03$It has been a staple of drama to feature an innocent young protagonist, eager to make a mark on the world, who is stymied by an indifferent or hostile society. Since the playwrights of such works wished the audience to empathize with the protagonist, historians do not regard these plays as serious revelations of what the societies presented in the plays were really like.$batch03$ AND q.prompt=$batch03$Which one of the following, if true, most helps to explain the viewpoint of the historians described above?$batch03$ AND q.correct_choice=$batch03$B$batch03$) THEN RAISE EXCEPTION 'Question changed: PT120-S4-Q18'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch03$PT120-S4-Q18$batch03$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT120-S4-Q18'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch03$PT120-S4-Q18$batch03$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch03$Given that$batch03$, $batch03$Playwrights wanted the audience to empathize with an innocent protagonist facing a hostile society.$batch03$), (1, $batch03$How can it be that$batch03$, $batch03$Historians conclude these plays do not seriously reveal what those societies were really like?$batch03$), (2, $batch03$Evaluate$batch03$, $batch03$We need the link from "wanted empathy" to "not accurate." If playwrights made society look worse than it was to make the hero more sympathetic, the plays would distort the society. That is the missing step.$batch03$), (3, $batch03$Goal$batch03$, $batch03$Find that playwrights distort society to win sympathy for the hero.$batch03$)) v(position,label,body) WHERE q.qid=$batch03$PT120-S4-Q18$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch03$A$batch03$, $batch03$Whether playwrights criticize their own society more than others does not connect the wish for empathy to inaccuracy.$batch03$), ($batch03$B$batch03$, $batch03$Playwrights exaggerate a society's weaknesses for dramatic effect. A hostile society makes the hero sympathetic, and the exaggeration is why historians distrust the portrait.$batch03$), ($batch03$C$batch03$, $batch03$If plays tend to give useful information about their society, the historians' skepticism is harder to explain.$batch03$), ($batch03$D$batch03$, $batch03$This says plays often reveal their societies seriously, which contradicts the historians' view.$batch03$), ($batch03$E$batch03$, $batch03$Popularity is never mentioned, and this does not connect the playwrights' aims to inaccuracy.$batch03$)) v(letter,body) WHERE q.qid=$batch03$PT120-S4-Q18$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
